import json
from unittest.mock import patch
import openai_client

class Response:
    headers = {\"x-request-id\": \"req_test\"}
    def __enter__(self): return self
    def __exit__(self, *args): pass
    def read(self, limit):
        assert limit == 10 * 1024 * 1024 + 1
        return json.dumps({\"output\": [{\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}]}]}).encode()

class Opener:
    def open(self, request, timeout):
        assert request.full_url == \"https://api.openai.com/v1/responses\"
        assert timeout == 12.0
        assert request.get_header(\"Authorization\") == \"Bearer test-key\"
        body = json.loads(request.data)
        assert body == {\"model\": \"test-model\", \"input\": \"private\", \"store\": False}
        return Response()

with patch(\"openai_client.urllib.request.build_opener\", return_value=Opener()):
    assert openai_client.send_prompt(\"private\", model=\"test-model\", api_key=\"test-key\", timeout=12) == \"hello\"

assert openai_client._extract_text({\"output_text\": \"direct\"}) == \"direct\"
print(\"checks passed\")
PY"

